      definitionJa: "権限をもつ者（上司）が部下に対して、矮小化（trivialization：部下の見方・不安・現実認識を軽んじ損なう）と苦痛付与（affliction：部下に痛み・苦しみを向ける）を行う否定的な職場行動（Kukreja & Pandey, 2023）。上司—部下関係を対象とする。操作、嘘、いじめ、洗脳とは区別する。原典自身は、いじめ、虐待的監督、有害なリーダーシップとの重なりを認めている。",
      domain: "組織行動・人的資源",
      relatedConcepts: ["abusive-supervision", "workplace-bullying", "workplace-incivility"],
