      verifiedAt: "2026-10-19",
      notes: "Galanis, Katsiroumpa, Vraka, Siskou, Konstantakopoulou, Moisoglou, Gallos, & Kaitelidou（2023）。The quiet quitting scale: Development and initial validation。AIMS Public Health, 10(4), 828–848。DOI 10.3934/publichealth.2023055。sourceUrl は https://doi.org/10.3934/publichealth.2023055 のみ。Received 2023-08-20、Accepted 2023-10-07、Published 2023-10-17。CC BY 4.0。PMC10764970。出版社 PDF の直リンクは載せない。原典の略称は QQS。本レコードの略称 QQS-9 は9項目であることを示す。9項目・3因子。Detachment（心理的離脱・4項目：原典番号 #7, #8, #11, #18）、Lack of initiative（主体性の欠如・3項目：#9, #10, #12）、Lack of motivation（動機づけの欠如・2項目：#3, #5）。5件法。叙述文7項目は同意形式（1＝strongly disagree～5＝strongly agree）。「How often」形式の2項目（#12, #18）は頻度形式（1＝never～5＝always）。reverseItems は原典番号 #3, #5, #12（逆転後に高得点ほど静かな退職が強い）。最終9項目へ振り直した番号ではない。採点は9項目の平均（1～5）を総得点、各因子も項目平均。高いほど静かな退職の水準が高い。原典はカットオフを設定していない。カットオフは別論文（Arch Hellen Med 2024）にあり、未確認のため使わない。開発の流れは、文献レビューと就業者6名の面接で38項目、専門家6名の CVR で18項目、認知面接5名・パイロット30名（face validity index .833–.967）、項目分析で9項目。開発標本はギリシャの公共・民間部門の就業者 922名（便宜標本、2023年6月、SNS・ブログ・メール・SMS・対面。参加条件は18歳以上でギリシャ語を理解できること）。半分割で EFA n=461、CFA n=461。EFA（promax）3因子の分散説明率 65.028%（Table 3）。CFA は χ²/df=3.184、RMSEA=0.069（90% CI 0.052–0.087）、GFI=0.964、NFI=0.939、CFI=0.957、標準化負荷 0.478–0.878、detachment と lack of initiative の因子間相関 r=0.81（Figure 2）。信頼性（全922名、Table 5）は総得点 α=0.803、ω=0.806、Detachment α=0.707、ω=0.711、Lack of initiative α=0.706、ω=0.735、Lack of motivation α=0.747（ω は項目数不足で算出不可）。再検査（50名、2週間）は項目の Cohen's κ 0.836–0.945、総得点 ICC 0.993、因子 ICC 0.987–0.992。併存妥当性（Table 4、n=922）は総得点と JSS r=−0.46、CBI 業務関連 0.45、個人 0.39、クライアント関連 0.34、単一項目バーンアウト 0.29、離職意向（Spearman）0.48。実施言語は本文に明記がないため断定しない。参加条件はギリシャ語理解。論文の項目表記は英語。英語版・ギリシャ語版などは著者サイトで配布。usagePermission は research-use。著者サイト（http://scholar.uoa.gr/pegalan/quiet-quitting-scale）は、非営利の教育・研究目的は無償、関連論文の引用が条件、翻訳は著者へ写しを送ることが条件、と明記する（2026-10-19 確認）。論文自体は CC BY 4.0。商用利用の条件は未確認。itemPublicationStatus は source-open。原典（CC BY）の Table 3 に9項目の英文がある。アトラスには転載しない。items は空。日本語は unconfirmed。著者サイトの翻訳版一覧（ドイツ語、ギリシャ語、ラトビア語、イタリア語、中国語、トルコ語、ポルトガル語、タイ語）に日本語はない。中国語版（Zhang ら 2025、BMC Nursing、DOI 10.1186/s12912-025-02921-4）などの他言語版は別レコードにしない。usageStudies は Xu ら（2025）のフル9項目1件（DOI 10.3389/fpsyg.2025.1616354。Frontiers in Psychology, 16, 1616354。2025-09-03。CC BY 4.0。PMC12442560）。中国のプライマリ・ヘルスケア職員、有効520名。原版では2項目が頻度形式だが、本研究は全項目を同意形式の5件法と記載しており、adaptation として記録する。中国語版 QQS（Zhang ら 2025）は引用していない。この標本の Cronbach's α=0.787。Table 2 対角の 0.746 は AVE で α ではない。考察のカットオフ 2.06 は採用しない。旗艦の responseFormat は変えない。開発論文は使用研究に入れない。ワーク・エンゲイジメントの低さ、バーンアウト、離職意向とは別。",
